/**
 * Partner sign-in: registered mobile number + a one-time 4-digit login code
 * generated by the operations team in the admin panel. Each code works once;
 * ops generate a fresh one for every sign-in.
 */
import { Ionicons } from '@expo/vector-icons';
import { useState } from 'react';
import { KeyboardAvoidingView, Platform, ScrollView, StyleSheet, TextInput, View } from 'react-native';
import { ApiError } from '@/api/client';
import { useAuth } from '@/auth/auth-context';
import { ErrorState } from '@/components/ErrorState';
import { OtpInput } from '@/components/partner/OtpInput';
import { Button } from '@/components/ui/Button';
import { Text } from '@/components/ui/Text';
import { colors, radius, spacing } from '@/theme';

export function RiderLoginForm() {
  const { loginRiderOtp } = useAuth();
  const [phone, setPhone] = useState('');
  const [code, setCode] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const digits = phone.replace(/\D/g, '');
  const canSubmit = digits.length === 10 && code.length === 4 && !busy;

  const submit = async () => {
    if (digits.length !== 10) {
      setError('Enter your 10-digit mobile number');
      return;
    }
    if (code.length !== 4) {
      setError('Enter the 4-digit login code');
      return;
    }
    setError(null);
    setBusy(true);
    try {
      await loginRiderOtp(`+91${digits}`, code);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Could not sign in. Check your connection.');
      setCode('');
      setBusy(false);
    }
  };

  return (
    <KeyboardAvoidingView style={styles.screen} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
      <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
        <View style={styles.hero}>
          <View style={styles.logoCircle}>
            <Ionicons name="bicycle" size={32} color={colors.primary} />
          </View>
          <Text variant="h2" style={styles.title}>Partner sign in</Text>
          <Text variant="bodySmall" style={styles.subtitle}>
            Enter your registered mobile number and the login code from your operations team.
          </Text>
        </View>

        {error ? <ErrorState message={error} variant="inline" title="Could not sign in" /> : null}

        <View style={styles.card}>
          <Text variant="label" style={styles.fieldLabel}>Mobile number</Text>
          <View style={styles.phoneRow}>
            <Text style={styles.countryCode}>+91</Text>
            <View style={styles.phoneDivider} />
            <TextInput
              style={styles.phoneInput}
              value={phone}
              onChangeText={(t) => setPhone(t.replace(/\D/g, '').slice(0, 10))}
              keyboardType="phone-pad"
              placeholder="98765 43210"
              placeholderTextColor={colors.outline}
              maxLength={10}
              textContentType="telephoneNumber"
              autoComplete="tel"
              accessibilityLabel="Mobile number"
            />
          </View>

          <Text variant="label" style={[styles.fieldLabel, { marginTop: spacing.lg }]}>Login code</Text>
          <OtpInput value={code} onChange={setCode} error={null} />

          <Button title="Sign in" onPress={submit} loading={busy} disabled={!canSubmit} style={{ marginTop: spacing.lg }} />
        </View>

        <View style={styles.helpBox}>
          <Ionicons name="information-circle" size={18} color={colors.info} />
          <Text variant="caption" style={styles.helpText}>
            {"Don't have a code? Ask your Khana Delivery operations manager. Each code works once — you'll need a new one the next time you sign in."}
          </Text>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, width: '100%' },
  content: { padding: spacing.lg, paddingTop: spacing.xl * 2, maxWidth: 480, width: '100%', alignSelf: 'center' },
  hero: { alignItems: 'center', marginBottom: spacing.lg },
  logoCircle: {
    width: 72, height: 72, borderRadius: 36, backgroundColor: colors.primaryFixed,
    alignItems: 'center', justifyContent: 'center', marginBottom: spacing.md,
  },
  title: { textAlign: 'center', color: colors.text },
  subtitle: { textAlign: 'center', color: colors.textMuted, marginTop: spacing.sm },
  card: {
    backgroundColor: colors.surface, borderRadius: radius.lg, padding: spacing.lg,
    borderWidth: 1, borderColor: colors.borderLight, marginTop: spacing.md,
  },
  fieldLabel: { color: colors.textMuted, marginBottom: spacing.sm },
  phoneRow: {
    flexDirection: 'row', alignItems: 'center', borderWidth: 1.5, borderColor: colors.border,
    borderRadius: radius.md, paddingHorizontal: spacing.md, height: 52, backgroundColor: colors.surface,
  },
  countryCode: { fontSize: 16, fontWeight: '700', color: colors.text },
  phoneDivider: { width: 1, height: 24, backgroundColor: colors.border, marginHorizontal: spacing.md },
  phoneInput: { flex: 1, fontSize: 17, color: colors.text, letterSpacing: 1 },
  helpBox: {
    flexDirection: 'row', gap: spacing.sm, alignItems: 'flex-start', marginTop: spacing.lg,
    backgroundColor: colors.infoSoft, borderRadius: radius.md, padding: spacing.md,
  },
  helpText: { flex: 1, color: colors.onInfoContainer, lineHeight: 18 },
});
